<template>
  <sf-page-layout class="v3-collection" :title="title" extended @back="$emit('action','back')">
    <p class="collection-intro">{{ kind==='movement'?'A little movement. A stronger you. Choose a workout and make it your own.':'Explore real-world routes for your next workout.' }}</p>
    <template v-if="kind==='movement'"><article v-for="content in sortedContents" :key="content.id" class="movement-library-card" :data-content-id="content.id"><div class="movement-library-card__image"><img :src="groupPoster(content)" alt=""/><span v-if="content.training&&content.training.vision.supported" class="movement-library-card__vision"><training-icon name="scan" :size="14"/>Vision ready</span><sf-badge :tone="content.tier==='free'?'success':'accent'">{{ content.tier==='free'?'Free':'Premium' }}</sf-badge></div><div class="movement-library-card__body"><h2>{{ content.name }}</h2><p>{{ content.durationMinutes }} min · {{ content.training?content.training.steps.length:3 }} movements <span v-if="content.training&&content.training.vision.supported">· {{ content.training.vision.framing==='upper_body'?'Upper body':'Full body' }}</span></p><sf-button block :disabled="busy" @click="$emit('action','open-movement:'+content.id)">View workout</sf-button></div></article></template>
    <template v-else><sf-card v-for="content in contents" :key="content.id" class="collection-card" :title="content.name" :data-content-id="content.id"><template #accessory><sf-badge :tone="content.tier==='free'?'success':'accent'">{{ content.tier==='free'?'Free':'Premium' }}</sf-badge></template><p v-if="content.durationMinutes">{{ content.durationMinutes }} min</p><p v-if="content.description&&!content.sample">{{ content.description }}</p><mvp-access-note :content="content" @action="$emit('action',$event)"/><template #footer><sf-button :disabled="busy" @click="$emit('action','start-content:'+content.id)">Start</sf-button></template></sf-card></template>
    <sf-feedback v-if="!contents.length" tone="empty" :title="'No '+title.toLowerCase()+' available'" description="Your content will appear here when it is published."/>
  </sf-page-layout>
</template>
<script>
import {SfPageLayout,SfCard,SfBadge,SfButton,SfFeedback} from '@/design-system'
import MvpAccessNote from './MvpAccessNote'
import TrainingIcon from '@/features/movement/TrainingIcon'
export default {components:{MvpAccessNote,SfPageLayout,SfCard,SfBadge,SfButton,SfFeedback,TrainingIcon},props:{contents:{type:Array,default:()=>[]},kind:String,busy:Boolean},computed:{title(){return this.kind==='movement'?'Movements':'World Tour'},sortedContents(){return [...this.contents].sort((a,b)=>Number(b.code==='vision_studio_workout')-Number(a.code==='vision_studio_workout')||Number(!!b.training?.vision.supported)-Number(!!a.training?.vision.supported))}},methods:{groupPoster(content){if(content.code==='vision_studio_workout')return process.env.BASE_URL+'assets/movement/real/shoulder-rolls.jpg';return process.env.BASE_URL+'assets/movement/media/'+(content.training?.vision.framing==='upper_body'?'curl':'squat')+'.png'}}}
</script>
<style scoped>
.v3-collection{height:100%}.v3-collection >>> .sf-page-layout__content{display:flex;flex-direction:column;gap:16px}.collection-intro{font-size:14px;line-height:22px;color:var(--sf-text-secondary);margin:0}.collection-card p{font-size:14px;line-height:22px;color:var(--sf-text-secondary)}.collection-card .sf-button{min-height:48px}.collection-card >>> .sf-card__title{font-size:18px;line-height:26px}
.movement-library-card{overflow:hidden;border-radius:20px;background:#ffffffba;border:1px solid #fff;box-shadow:0 6px 25px #23335009}.movement-library-card__image{height:156px;position:relative;overflow:hidden;background:#e9ebee}.movement-library-card__image>img{width:100%;height:100%;object-fit:cover;object-position:50% 28%}.movement-library-card__image>.sf-badge{position:absolute;right:12px;top:12px}.movement-library-card__vision{position:absolute;left:12px;top:12px;display:flex;align-items:center;gap:5px;font-size:10px;line-height:17px;color:#344b4b;background:#ecfff5dd;border:1px solid #fff;border-radius:7px;padding:4px 8px;backdrop-filter:blur(14px)}.movement-library-card__body{padding:16px}.movement-library-card h2{font-size:19px;line-height:26px;font-weight:650;letter-spacing:-.4px;margin:0}.movement-library-card p{font-size:11px;line-height:18px;color:#828c9a;margin:6px 0 16px}.movement-library-card .sf-button{font-size:14px;line-height:22px;min-height:44px}
</style>
